@wrap_model_call
def apply_step_config(request: ModelRequest, handler) -> ModelResponse:
    step = request.state.get("current_step", "triage")
    configs = {
        "triage": {"prompt": "Collect warranty info", "tools": [record_warranty_status]},
        "specialist": {"prompt": "Provide solutions", "tools": [provide_solution]},
    }
    config = configs[step]
    request = request.override(
        system_prompt=config["prompt"], tools=config["tools"]
    )
    return handler(request)

def route_after_agent(state) -> str:
    messages = state.get("messages", [])
    if messages:
        last_msg = messages[-1]
        if isinstance(last_msg, AIMessage) and not last_msg.tool_calls:
            return "__end__"
    return state.get("active_agent") or "sales_agent"

def route_query(state: State):
